const test=require('node:test'),assert=require('node:assert/strict');
async function fixture(){const T=await import('../vendor/three.module.js'),m=await import('../sandbox-camera.mjs');const camera=new T.PerspectiveCamera(38,1280/720,.1,1600);camera.position.set(30,45,70);const orbit={target:new T.Vector3(4,2,7),minDistance:1.2,maxDistance:800,maxPolarAngle:Math.PI*.47,enabled:true,update(){camera.lookAt(this.target);camera.updateMatrixWorld();}};orbit.update();return {T,camera,orbit,...m};}
function hex(T,r=5){return Array.from({length:12},(_,i)=>new T.Vector3(10+Math.sin(i*Math.PI/3)*r,i<6?2:4,20+Math.cos(i*Math.PI/3)*r));}
const desktop={width:1280,height:720,left:190,top:68,right:890,bottom:634},phone={width:390,height:844,left:16,top:68,right:374,bottom:419};
test('hex focus is 35 degrees, preserves azimuth, and fits the actual visible desktop and phone area',async()=>{
 for(const area of [desktop,phone])for(const radius of [.5,5]){const {T,camera,orbit,createSandboxFocus}=await fixture();camera.aspect=area.width/area.height;camera.updateProjectionMatrix();const offset=camera.position.clone().sub(orbit.target),azimuth=Math.atan2(offset.x,offset.z),focus=createSandboxFocus(T,camera,orbit),points=hex(T,radius);assert(focus.focus(points,area));const next=camera.position.clone().sub(orbit.target);assert(Math.abs(Math.asin(next.y/next.length())*180/Math.PI-35)<1e-10);assert(Math.abs(Math.atan2(next.x,next.z)-azimuth)<1e-10);for(const p of points){const ndc=p.clone().project(camera),x=(ndc.x+1)*area.width/2,y=(1-ndc.y)*area.height/2;assert(x>=area.left&&x<=area.right,`x ${x}`);assert(y>=area.top&&y<=area.bottom,`y ${y}`);}assert(focus.active);}
});
test('Back restores the original camera, zoom and off-center framing after pan and multiple hexes',async()=>{
 const {T,camera,orbit,createSandboxFocus}=await fixture();camera.zoom=1.2;camera.setViewOffset(1280,720,120,-40,1280,720);const before={position:camera.position.clone(),target:orbit.target.clone(),zoom:camera.zoom,view:{...camera.view}},focus=createSandboxFocus(T,camera,orbit);focus.focus(hex(T),desktop);camera.position.addScalar(8);orbit.target.addScalar(8);focus.focus(hex(T).map(p=>p.addScalar(30)),desktop);assert(focus.restore(desktop));assert(camera.position.distanceTo(before.position)<1e-10);assert(orbit.target.distanceTo(before.target)<1e-10);assert.equal(camera.zoom,before.zoom);assert.deepEqual(camera.view,before.view);assert.equal(focus.active,false);assert.equal(focus.restore(),false);
});
test('restore adapts view offsets after resize and explicit fit discards the bookmark',async()=>{
 const {T,camera,orbit,createSandboxFocus}=await fixture();camera.setViewOffset(1280,720,120,-40,1280,720);const focus=createSandboxFocus(T,camera,orbit);focus.focus(hex(T),desktop);focus.restore(phone);assert.equal(camera.view.offsetX,120*390/1280);assert(Math.abs(camera.view.offsetY+40*844/720)<1e-10);focus.focus(hex(T),phone);focus.clear();assert.equal(focus.restore(),false);assert.equal(focus.focus([],phone),false);
});
test('focus honors existing zoom and polar limits',async()=>{
 const {T,camera,orbit,createSandboxFocus}=await fixture();orbit.maxDistance=10;orbit.maxPolarAngle=.5;const focus=createSandboxFocus(T,camera,orbit);focus.focus(hex(T,50),desktop);assert(Math.abs(camera.position.distanceTo(orbit.target)-10)<1e-10);assert(Math.abs(camera.position.clone().sub(orbit.target).normalize().y-Math.cos(.5))<1e-10);
});
async function gestures(){const {bindHexFocus}=await import('../sandbox-camera.mjs'),element=new EventTarget(),hits=[];let allowed=true,time=0;const cleanup=bindHexFocus(element,{canFocus:()=>allowed,pick:()=>({q:2,r:3}),focus:cell=>hits.push(cell)});function send(type,props={}){const e=new Event(type,{cancelable:true});for(const [key,value] of Object.entries({button:0,pointerId:1,pointerType:'mouse',clientX:30,clientY:40,timeStamp:time+=30,...props}))Object.defineProperty(e,key,{value});element.dispatchEvent(e);}function click(props={}){send('pointerdown',props);send('pointerup',props);}return {send,click,hits,cleanup,set allowed(v){allowed=v;}};}
test('two clicks focus once; modified clicks, drags, cancelled gestures and armed placement do not',async()=>{
 for(const kind of ['plain','shift','ctrl','meta','alt','drag','cancel','armed']){const g=await gestures();const props=kind==='plain'?{}:kind==='shift'?{shiftKey:true}:kind==='ctrl'?{ctrlKey:true}:kind==='meta'?{metaKey:true}:kind==='alt'?{altKey:true}:{};if(kind==='armed')g.allowed=false;g.click(props);g.allowed=true;g.send('pointerdown',props);if(kind==='drag'){g.send('pointermove',{clientX:90});g.send('pointermove');}if(kind==='cancel')g.send('pointercancel');g.send('pointerup',props);g.send('dblclick',props);assert.equal(g.hits.length,kind==='plain'?1:0,kind);g.cleanup();}
});
test('double tap focuses, while a two-finger gesture does not',async()=>{
 const g=await gestures();g.click({pointerType:'touch'});g.click({pointerType:'touch'});await Promise.resolve();assert.equal(g.hits.length,1);g.send('pointerdown',{pointerType:'touch'});g.send('pointerdown',{pointerType:'touch',pointerId:2});g.send('pointerup',{pointerType:'touch',pointerId:2});g.send('pointerup',{pointerType:'touch'});g.click({pointerType:'touch'});await Promise.resolve();assert.equal(g.hits.length,1);g.cleanup();
});

test('native mouse double-click timing follows the browser even when rendering delays events',async()=>{const g=await gestures();g.send('pointerdown',{timeStamp:1});g.send('pointerup',{timeStamp:800});g.send('pointerdown',{timeStamp:1500});g.send('pointerup',{timeStamp:2200});g.send('dblclick',{timeStamp:2201});assert.equal(g.hits.length,1);g.cleanup();});
